using UnityEngine;
using UnityEditor;
using System;
using System.IO;
using System.Linq;
using System.Text;
using ConRoi.Investigation.V36;
using Object = UnityEngine.Object;

namespace Unity.AI.Assistant.Agent.Dynamic.Extension.Editor
{
    internal class CommandScript : IRunCommand
    {
        public void Execute(ExecutionResult r)
        {
            var s = Object.FindFirstObjectByType<InvestigationSession>();
            if (!EditorApplication.isPlaying)
                throw new Exception("Play required");
            if (Screen.width != 1920 || Screen.height != 932)
                throw new Exception("Calibrated GameView 1920x932 required, got " + Screen.width + "x" + Screen.height);
            s.SaveDirectoryOverride = Path.GetFullPath("Test/KetQua/investigation_r102/cipher-ui-profile");
            s.data.mapping.Clear();
            s.data.evidence.RemoveAll(e => e.id == "decoded");
            s.OpenPage("cipher");
            var w = EditorWindow.GetWindow(Type.GetType("UnityEditor.GameView,UnityEditor"));
            Action<float, float> click = (x, y) =>
            {
                var p = new Vector2(x / 1.25f, (y + 55) / 1.25f);
                w.SendEvent(new Event{type = EventType.MouseDown, button = 0, mousePosition = p});
                w.SendEvent(new Event{type = EventType.MouseUp, button = 0, mousePosition = p});
            };
            var log = new StringBuilder("Known-solution UI test through GameView mouse/text events; not newcomer reasoning test. API clears only this private test board.\n");
            int step = 0;
            double next = EditorApplication.timeSinceStartup + .8;
            EditorApplication.CallbackFunction tick = null;
            tick = () =>
            {
                if (EditorApplication.timeSinceStartup < next)
                    return;
                next = EditorApplication.timeSinceStartup + .4;
                try
                {
                    if (step < 15)
                    {
                        char c = InvestigationContent.Alphabet[step];
                        click(455 + 83.5f * step, 565);
                        w.SendEvent(new Event{type = EventType.KeyDown, keyCode = (KeyCode)((int)KeyCode.A + c - 'A'), character = c});
                        w.SendEvent(new Event{type = EventType.KeyUp, keyCode = (KeyCode)((int)KeyCode.A + c - 'A'), character = c});
                        step++;
                        return;
                    }

                    if (step == 15)
                    {
                        log.AppendLine("mapping=" + string.Join(",", s.data.mapping.Select(m => m.pose + "=" + m.letter)));
                        if (s.data.mapping.Count(m => m.pose == m.letter) != 15)
                            throw new Exception("UI fields did not all receive intended characters");
                        click(1100, 683);
                        step++;
                        return;
                    }

                    log.AppendLine("UI record lead=" + s.Has("decoded") + " finalized=" + s.data.finalized);
                    if (!s.Has("decoded") || s.data.finalized)
                        throw new Exception("Lead not recorded or case auto-finalized");
                    s.Save();
                    ScreenCapture.CaptureScreenshot("Test/BangChung/investigation_r102/cipher-ui-solved.png");
                    File.WriteAllText("Test/KetQua/investigation_r102/cipher-ui-solved.txt", log.ToString());
                    EditorApplication.update -= tick;
                }
                catch (Exception e)
                {
                    log.AppendLine("FAIL " + e);
                    File.WriteAllText("Test/KetQua/investigation_r102/cipher-ui-solved.txt", log.ToString());
                    EditorApplication.update -= tick;
                }
            };
            EditorApplication.update += tick;
            r.Log("Started known-solution UI trial in private profile, ~8s");
        }
    }
}

